INSERT INTO `sys_oper_log` VALUES (529, '博客', 2, 'com.smartLive.blog.controller.BlogController.edit()', 'PUT', 1, NULL, NULL, '/blog', '127.0.0.1', '', '{\"content\":\"今天来探店祖庙商圈的坤坤蜀味轩小火锅呀。这家店位于南海区桂城街道桂海花园2区，人均128元，评分显示4.8分，营业时间是10:00-23:00。\\n\\n说实话，这次体验不太理想。首先菜品方面，食材新鲜度有待提升，部分肉类和蔬菜看起来不太新鲜，影响口感。其次店铺人气太旺，就餐环境比较拥挤，等位时间较长，用餐体验不够舒适。另外服务方面也存在不足，服务员响应不够及时，加汤、换碟需要多次催促，整体服务效率偏低。\\n\\n虽然评分显示4.8分，但实际体验与评分存在一定差距。128元的人均消费在小火锅中不算低，但菜品质量和服务水平确实有待提升。如果你对用餐环境和服务要求较高，建议谨慎选择。\",\"id\":67,\"images\":\"/2026/03/10/微信图片_20260130165747_59_1463_20260310114151A001.jpg\",\"params\":{},\"shopId\":1,\"status\":0,\"title\":\"避雷！佛山这家网红小火锅的真实体验\",\"updateTime\":\"2026-03-13 17:01:17\"}', '{\"data\":1,\"success\":true}', 0, NULL, '2026-03-13 17:01:18', 72);
INSERT INTO `sys_oper_log` VALUES (530, '博客', 2, 'com.smartLive.blog.controller.BlogController.edit()', 'PUT', 1, NULL, NULL, '/blog', '127.0.0.1', '', '{\"content\":\"今天来探店祖庙商圈的坤坤蜀味轩小火锅呀。这家店位于南海区桂城街道桂海花园2区，人均128元，评分显示4.8分，营业时间是10:00-23:00。\\n\\n说实话，这次体验不太理想。首先菜品方面，食材新鲜度有待提升，部分肉类和蔬菜看起来不太新鲜，影响口感。其次店铺人气太旺，就餐环境比较拥挤，等位时间较长，用餐体验不够舒适。另外服务方面也存在不足，服务员响应不够及时，加汤、换碟需要多次催促，整体服务效率偏低。\\n\\n虽然评分显示4.8分，但实际体验与评分存在一定差距。128元的人均消费在小火锅中不算低，但菜品质量和服务水平确实有待提升。如果你对用餐环境和服务要求较高，建议谨慎选择。\",\"id\":67,\"images\":\"/2026/03/10/微信图片_20260130165747_59_1463_20260310114151A001.jpg\",\"params\":{},\"shopId\":1,\"status\":1,\"title\":\"避雷！佛山这家网红小火锅的真实体验\",\"updateTime\":\"2026-03-13 17:01:25\"}', '{\"data\":1,\"success\":true}', 0, NULL, '2026-03-13 17:01:25', 16);
